CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role = 'owner'), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE FUNCTION public.is_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role='owner') $$;
REVOKE ALL ON FUNCTION public.is_owner() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_owner() TO authenticated;
CREATE FUNCTION public.assign_personal_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'owner'); RETURN NEW; EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'Esta ferramenta é de uso pessoal. Cadastro indisponível.'; END; $$;
CREATE TRIGGER assign_personal_owner AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_personal_owner();
CREATE TABLE public.searches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, city text NOT NULL, state text NOT NULL CHECK(char_length(state)=2), niche text NOT NULL, run_id text, dataset_id text, status text NOT NULL DEFAULT 'idle' CHECK(status IN ('idle','running','ready','exhausted','failed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,city,state,niche));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.searches TO authenticated; GRANT ALL ON public.searches TO service_role;
ALTER TABLE public.searches ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_searches ON public.searches TO authenticated USING(user_id=auth.uid() AND public.is_owner()) WITH CHECK(user_id=auth.uid() AND public.is_owner());
CREATE TABLE public.businesses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, place_id text NOT NULL, data jsonb NOT NULL DEFAULT '{}', website_type text NOT NULL CHECK(website_type IN ('sem site','só Instagram','só Facebook','só WhatsApp','só link na bio')), score double precision NOT NULL DEFAULT -1, is_lead boolean NOT NULL DEFAULT false, city text NOT NULL, state text NOT NULL, niche text NOT NULL, enrichment_run_id text, enrichment_dataset_id text, enrichment_status text NOT NULL DEFAULT 'idle' CHECK(enrichment_status IN ('idle','running','ready','failed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,place_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.businesses TO authenticated; GRANT ALL ON public.businesses TO service_role;
ALTER TABLE public.businesses ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_businesses ON public.businesses TO authenticated USING(user_id=auth.uid() AND public.is_owner()) WITH CHECK(user_id=auth.uid() AND public.is_owner());
CREATE TABLE public.reserves(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, search_id uuid NOT NULL REFERENCES public.searches(id) ON DELETE CASCADE, business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE CASCADE, shown_at timestamptz, batch_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(search_id,business_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.reserves TO authenticated; GRANT ALL ON public.reserves TO service_role;
ALTER TABLE public.reserves ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_reserves ON public.reserves TO authenticated USING(user_id=auth.uid() AND public.is_owner()) WITH CHECK(user_id=auth.uid() AND public.is_owner());
CREATE TABLE public.blocked_places(place_id text PRIMARY KEY);
GRANT SELECT,INSERT ON public.blocked_places TO authenticated; GRANT ALL ON public.blocked_places TO service_role;
ALTER TABLE public.blocked_places ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_blocks ON public.blocked_places TO authenticated USING(public.is_owner()) WITH CHECK(public.is_owner());
CREATE INDEX reserves_queue ON public.reserves(search_id,shown_at); CREATE INDEX reserves_business ON public.reserves(business_id); CREATE INDEX businesses_leads ON public.businesses(user_id,is_lead); CREATE INDEX searches_user ON public.searches(user_id);
CREATE FUNCTION public.take_batch(p_search uuid) RETURNS SETOF public.businesses LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE v_batch uuid := gen_random_uuid(); BEGIN PERFORM 1 FROM public.searches WHERE id=p_search FOR UPDATE; RETURN QUERY WITH chosen AS (SELECT r.id FROM public.reserves r JOIN public.businesses b ON b.id=r.business_id WHERE r.search_id=p_search AND r.shown_at IS NULL AND NOT b.is_lead AND NOT EXISTS(SELECT 1 FROM public.blocked_places x WHERE x.place_id=b.place_id) ORDER BY b.score DESC,b.place_id LIMIT 10 FOR UPDATE OF r), changed AS (UPDATE public.reserves r SET shown_at=now(),batch_id=v_batch WHERE r.id IN(SELECT id FROM chosen) RETURNING r.business_id) SELECT b.* FROM public.businesses b JOIN changed c ON c.business_id=b.id ORDER BY b.score DESC,b.place_id; END; $$;
REVOKE ALL ON FUNCTION public.take_batch(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.take_batch(uuid) TO authenticated;
CREATE FUNCTION public.discard_place(p_place text) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ BEGIN INSERT INTO public.blocked_places(place_id) VALUES(p_place) ON CONFLICT DO NOTHING; DELETE FROM public.businesses WHERE place_id=p_place; END; $$;
REVOKE ALL ON FUNCTION public.discard_place(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.discard_place(text) TO authenticated;